<?php $pageTitle='Student academic history';
$describe=static function(?string $json):string{
 $data=json_decode($json??'null',true);if(!is_array($data))return 'No previous placement';$parts=[];
 foreach(['academic_session'=>'Session','study_year'=>'Year','current_year_of_study'=>'Year','semester'=>'Semester','section'=>'Section','placement_status'=>'Academic status','status'=>'Record status','mode'=>'Progression','semester_delay'=>'Semester delay'] as $key=>$label)if(isset($data[$key]))$parts[]=$label.': '.ucwords(str_replace('_',' ',(string)$data[$key]));
 return implode("\n",$parts);
}; ?>
<div class="academic-progression-page">
<section class="page-heading"><div><p class="eyebrow">Academic progression</p><h1><?= e($student['name']) ?></h1><p><?= e($student['roll_no_original'].' — '.($student['batch_label']??'Batch unassigned')) ?></p></div><a class="secondary-button" href="<?= e(url('students')) ?>">Student directory</a></section>
<?php if($success):?><div class="alert success" role="status"><?= e($success) ?></div><?php endif;?><?php if($error):?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif;?>
<section class="panel form-section"><h2>Progression rule</h2><p>Automatic progression uses the admission batch and academic calendar. Hold freezes the saved semester until released. A delay of 2 semesters represents a repeated academic year; it remains in effect after resuming automatic progression.</p>
<form method="post" class="record-form" action="<?= e(url('academic-rollover/students/'.$student['id'].'/control')) ?>"><?= csrf_field() ?><div class="form-grid two">
<label>Mode<select name="mode"><?php foreach(['automatic'=>'Automatic progression','hold'=>'Hold current placement','withdrawn'=>'Withdrawn / inactive','completed'=>'Completion verified'] as $value=>$label):?><option value="<?= $value ?>" <?= $progressionControl['mode']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label>
<label>Delay in semesters<input type="number" name="semester_delay" min="0" max="24" value="<?= (int)$progressionControl['semester_delay'] ?>" required></label>
<label>Reason / completion evidence<textarea name="reason" maxlength="500" required><?= e($progressionControl['reason']) ?></textarea></label>
<label>Completion verification<select name="completion_confirmed"><option value="0">Not confirming completion</option><option value="1">I verified programme completion</option></select><small>Required only when selecting Completion verified. Reaching the end year alone is insufficient.</small></label></div>
<p>Resuming with a zero delay returns the student to the batch's calendar semester. Update the delay when a repeated year must be retained.</p><button class="primary-button">Save rule and reconcile</button></form></section>
<section class="panel table-panel"><div class="table-toolbar"><strong>Academic placements</strong></div><div class="table-scroll"><table><thead><tr><th>Session</th><th>Term</th><th>Year / semester</th><th>Section</th><th>Placement status</th><th>Course registrations</th></tr></thead><tbody><?php foreach($terms as $term):?><tr><td><?= e($term['academic_session']) ?></td><td><?= (int)$term['term'] ?></td><td>Year <?= (int)$term['study_year'] ?> / Sem <?= (int)$term['semester'] ?></td><td><?= e($term['section']) ?></td><td><?= e(ucwords(str_replace('_',' ',$term['placement_status']))) ?></td><td><?= (int)$term['course_count'] ?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel table-panel"><div class="table-toolbar"><strong>Change history</strong><span>Most recent 30 changes</span></div><div class="table-scroll"><table><thead><tr><th>Date</th><th>Action</th><th>Previous placement</th><th>New placement / rule</th><th>Reason</th></tr></thead><tbody><?php foreach($academicHistory as $entry):?><tr><td><?= e($entry['created_at']) ?></td><td><?= e(ucwords(str_replace('_',' ',$entry['action']))) ?></td><td><span class="academic-history-value"><?= e($describe($entry['old_values'])) ?></span></td><td><span class="academic-history-value"><?= e($describe($entry['new_values'])) ?></span></td><td><?= e($entry['reason']) ?></td></tr><?php endforeach;?></tbody></table></div></section>
</div>
